ALTER TABLE public.pm_tasks ADD COLUMN duration_value numeric CHECK(duration_value>=0), ADD COLUMN duration_unit text NOT NULL DEFAULT 'days' CHECK(duration_unit IN('hours','days','weeks','months','years')); UPDATE public.pm_tasks SET duration_value=duration; ALTER TABLE public.pm_phases ADD COLUMN duration_value numeric CHECK(duration_value>=0), ADD COLUMN duration_unit text NOT NULL DEFAULT 'days' CHECK(duration_unit IN('hours','days','weeks','months','years'));